<?php
require BASE_PATH.'/resources/views/categories/operations.php';
$viewState=category_view_state($categories,$filters);
$categoryCount=count($categories);$subcategoryCount=array_sum(array_map(fn($c)=>count($c['subcategories']),$categories));
function categoryHidden(string $action,string $level,?int $id=null): void { ?>
<input type="hidden" name="csrf" value="<?= e(csrf()) ?>"><input type="hidden" name="action" value="<?= e($action) ?>"><input type="hidden" name="level" value="<?= e($level) ?>"><?php if ($id): ?><input type="hidden" name="id" value="<?= $id ?>"><?php endif;
}
function categoryFields(array $entry=[],bool $submit=true): void { ?>
<div class="category-fields"><label>Name<input type="text" name="name" required maxlength="150" value="<?= e($entry['name'] ?? '') ?>"></label><label>Slug <span class="muted-inline">optional for new entries</span><input type="text" name="slug" maxlength="190" pattern="[a-z0-9]+(-[a-z0-9]+)*" value="<?= e($entry['slug'] ?? '') ?>" placeholder="Generated from name"></label><label class="wide">Description<textarea name="description" maxlength="5000" rows="2"><?= e($entry['description'] ?? '') ?></textarea></label><label>Status<select name="status"><option value="active" <?= ($entry['status'] ?? '')==='active'?'selected':'' ?>>Active</option><option value="inactive" <?= ($entry['status'] ?? '')==='inactive'?'selected':'' ?>>Inactive</option></select></label><input type="hidden" name="sort_order" value="<?= (int)($entry['sort_order'] ?? 0) ?>"></div><?php if ($submit): ?><button class="secondary" type="submit">Save changes</button><?php endif; ?>
<?php }
function orderControls(string $level,int $id,string $label): void { ?>
<form method="post" action="<?= e(url('/categories')) ?>" class="order-form"><?php categoryHidden('reorder',$level,$id); ?><button name="direction" value="up" title="Move up" aria-label="Move <?= e($label) ?> up">↑</button><button name="direction" value="down" title="Move down" aria-label="Move <?= e($label) ?> down">↓</button></form>
<?php }
?>
<div id="category-workspace" data-page="categories">
<section class="page-heading"><div><h1>Categories</h1><p>Manage your two-level spare parts catalogue.</p></div><span class="label-chip"><?= $categoryCount ?> main categories · <?= $subcategoryCount ?> subcategories</span></section>
