<div class="category-table-heading"><span>Category / subcategory</span><span>Products &amp; status</span><span>Actions</span></div><div class="category-list"><?php foreach ($categories as $category): $id=(int)$category['id']; ?><details class="category-card" id="category-<?= $id ?>"<?= in_array($id,$viewState['categories'],true)?'':' hidden' ?>><summary class="category-summary" data-name="<?= e($category['name'].' '.$category['slug'].' '.$category['description']) ?>" data-status="<?= $category['archived_at']?'archived':e($category['status']) ?>"><span class="disclosure" aria-hidden="true">›</span><div class="category-title"><strong><?= e($category['name']) ?></strong><span><?= count($category['subcategories']) ?> subcategories · <a class="text-link" href="<?= e(url('/products')) ?>&amp;status=all&amp;category_id=<?= $id ?>"><?= (int)$category['product_count'] ?> products</a></span></div><span class="status-badge <?= $category['status']==='inactive'?'is-inactive':'' ?>"><?= $category['archived_at']?'Archived':e(ucfirst($category['status'])) ?></span><span class="category-row-actions"><?php if (!$category['archived_at']): ?><button class="icon-button" type="button" data-add-category="subcategory" data-parent-id="<?= $id ?>" aria-label="Add subcategory to <?= e($category['name']) ?>" title="Add subcategory"><?= icon('plus') ?></button><button class="icon-button" type="button" data-edit-category="category" data-edit-id="<?= $id ?>" aria-label="Edit <?= e($category['name']) ?>" title="Edit category"><?= icon('edit') ?></button><?php endif; ?><span class="category-menu-wrap"><button class="icon-button" type="button" data-main-menu aria-expanded="false" aria-label="More actions for <?= e($category['name']) ?>" title="More actions">⋯</button><span class="main-category-dropdown" hidden><?php if (!$category['archived_at']): ?><button type="button" data-main-action="merge" data-id="<?= $id ?>">Merge…</button><button type="button" data-main-action="archive" data-id="<?= $id ?>">Archive…</button><?php else: ?><button type="button" data-main-action="restore" data-id="<?= $id ?>">Restore…</button><?php endif; ?><button type="button" data-main-action="delete" data-id="<?= $id ?>">Delete permanently…</button></span></span></span></summary><div class="category-content">
<?php if (!$category['archived_at']): ?><div class="category-toolbar"><span class="muted-inline"><?= (int)$category['direct_product_count'] ?> products without a subcategory</span><?php orderControls('category',$id,$category['name']); ?></div>
