<?php if ($sub['archived_at']): categoryLifecycle('subcategory',$subId); else: ?><button type="button" class="icon-button subcategory-edit" data-edit-category="subcategory" data-edit-id="<?= $subId ?>" title="Edit subcategory" aria-label="Edit <?= e($sub['name']) ?>"><?= icon('edit') ?></button>
